pageStyle:
td.evidencestrength {
padding: 0 !important;
}

td.evidencestrength span {
display: block;
width: 100%;
height: 100%;
padding-top: 6px;
}

td.evidencestrength span.v-strong {
 background-color: #04884560;
}

td.evidencestrength span.v-moderate {
 background-color: #04884540;
}
td.evidencestrength span.v-low {
    background-color: #04884520;
}
